"use client"

import * as React from "react"
import { ChevronLeft, ChevronRight } from "lucide-react"
import { IconButton } from "@/components/ui/icon-button"
import { cn } from "@/lib/utils"

function Carousel({
  children,
  className,
  label = "Carousel",
}: {
  children: React.ReactNode
  className?: string
  /** Accessible name of the scrolling region. */
  label?: string
}) {
  const scrollerRef = React.useRef<HTMLDivElement>(null)
  const [canScrollLeft, setCanScrollLeft] = React.useState(false)
  const [canScrollRight, setCanScrollRight] = React.useState(false)

  const updateScrollState = React.useCallback(() => {
    const el = scrollerRef.current
    if (!el) return
    setCanScrollLeft(el.scrollLeft > 1)
    setCanScrollRight(el.scrollLeft + el.clientWidth < el.scrollWidth - 1)
  }, [])

  React.useEffect(() => {
    const el = scrollerRef.current
    if (!el) return
    updateScrollState()
    el.addEventListener("scroll", updateScrollState, { passive: true })
    // Re-check when the track resizes or items are added/removed — the
    // container itself has no fixed width, so overflow only exists once
    // content is actually wider than the available space.
    const observer = new ResizeObserver(updateScrollState)
    observer.observe(el)
    return () => {
      el.removeEventListener("scroll", updateScrollState)
      observer.disconnect()
    }
  }, [updateScrollState, children])

  const scrollBy = (delta: number) => {
    scrollerRef.current?.scrollBy({ left: delta, behavior: "smooth" })
  }

  return (
    <div className={cn("relative w-full", className)}>
      <div
        ref={scrollerRef}
        // focusable, so the slides also scroll with the arrow keys
        tabIndex={0}
        role="region"
        aria-roledescription="carousel"
        aria-label={label}
        className="-mx-1 -mt-1 flex w-[calc(100%+0.5rem)] snap-x snap-mandatory scroll-px-1 gap-4 overflow-x-auto scroll-smooth px-1 pt-1 pb-2 outline-none [scrollbar-width:none] focus-visible:ring-1 focus-visible:ring-ring [&::-webkit-scrollbar]:hidden"
      >
        {React.Children.map(children, (child) => (
          <div className="shrink-0 snap-start">{child}</div>
        ))}
      </div>
      {canScrollLeft && (
        <IconButton
          variant="light"
          size="sm"
          shape="circle"
          className="absolute top-1/2 -left-3 -translate-y-1/2 shadow-md"
          onClick={() => scrollBy(-320)}
          aria-label="Previous"
        >
          <ChevronLeft />
        </IconButton>
      )}
      {canScrollRight && (
        <IconButton
          variant="light"
          size="sm"
          shape="circle"
          className="absolute top-1/2 -right-3 -translate-y-1/2 shadow-md"
          onClick={() => scrollBy(320)}
          aria-label="Next"
        >
          <ChevronRight />
        </IconButton>
      )}
    </div>
  )
}

export { Carousel }

import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

const iconButtonVariants = cva(
  "group/icon-button inline-flex shrink-0 items-center justify-center border border-transparent transition duration-fast ease-entrance outline-none select-none shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05)] active:translate-y-px disabled:pointer-events-none disabled:opacity-40 focus-visible:border-ring [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        plain: "bg-card border-border-control text-foreground hover:bg-muted",
        primary: "border-primary bg-primary text-primary-foreground hover:bg-primary/90",
        brand:
          "border-brand-primary bg-brand-primary text-brand-primary-foreground hover:bg-brand-primary/90",
        gradient:
          "border-primary bg-gradient-to-b from-[#6f74f5] to-primary text-primary-foreground shadow-[inset_0px_1px_2px_0px_rgba(255,255,255,0.35)] hover:brightness-105",
        dark: "bg-inverse text-text-inverse hover:bg-(--dark-400) hover:text-white",
        light: "bg-(--light-600) text-(--light-900) hover:bg-(--light-600)/90",
        outline: "bg-card border-primary text-foreground hover:bg-primary/5",
        // Figma Type=ghost / destructive (added Sep 2026)
        ghost: "bg-transparent text-foreground shadow-none hover:bg-muted",
        destructive:
          "border-destructive bg-destructive text-destructive-foreground hover:bg-destructive/90",
      },
      shape: {
        rounded: "rounded-md",
        circle: "rounded-full",
      },
      size: {
        sm: "size-8 [&_svg]:size-4",
        md: "size-9 [&_svg]:size-[18px]",
        lg: "size-10 [&_svg]:size-5",
        xl: "size-11 [&_svg]:size-[22px]",
        "2xl": "size-12 [&_svg]:size-6",
      },
    },
    defaultVariants: {
      variant: "primary",
      shape: "rounded",
      size: "md",
    },
  }
)

function IconButton({
  className,
  variant,
  shape,
  size,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof iconButtonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, shape, size, className }))}
      {...props}
    />
  )
}

export { IconButton, iconButtonVariants }
